<?php require_once __DIR__.'/config/config.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('index.php');verify_csrf();$id=(int)($_POST['post_id']??0);$uid=current_user_id();$s=$conn->prepare('DELETE FROM posts WHERE id=? AND (user_id=? OR ?=1)');$admin=is_admin()?1:0;$s->bind_param('iii',$id,$uid,$admin);$s->execute();flash($s->affected_rows?'Post deleted.':'You cannot delete that post.',$s->affected_rows?'success':'error');redirect('index.php');?>